INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('New Orleans Fairgrounds', '1751 Gentilly Blvd, New Orleans, LA 70119', 'Gentilly', 'Outdoor', 'https://www.fairgroundsracecourse.com', 'Home of Jazz Fest. Large outdoor festival grounds and race course. 15 stages during Jazz Fest. Cashless event.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Louis Armstrong Park', '701 N. Rampart Street, New Orleans, LA 70116', 'Treme', 'Outdoor', 'https://www.nola.gov/parks-and-parkways/parks-squares/armstrong-park/', 'Home of Congo Square. Major outdoor festival grounds in Tremé. Site of Congo Square Rhythms Festival and other Jazz Heritage Foundation events.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('UNO Lakefront Arena Festival Grounds', '6801 Franklin Ave, New Orleans, LA 70122', 'Gentilly', 'Outdoor', 'https://www.unopanthers.com/facilities/uno-lakefront-arena/1', 'Outdoor festival grounds adjacent to UNO Lakefront Arena on Lake Pontchartrain. Home of Hogs for the Cause.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Goldring Woldenberg Riverfront Park', '1 Canal St, New Orleans, LA 70130', 'French Quarter', 'Outdoor', NULL, 'Riverfront park along the Mississippi. New expanded stage location for French Quarter Festival 2026 — home of the Jack Daniel''s Stage.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Canal Place Cinema', '333 Canal St, New Orleans, LA 70130', 'CBD / Warehouse', 'Theater', 'https://canalplace.com', 'Cinema and event space in the Canal Place shopping center. Hosts the Overlook Film Festival.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Music Box Village', '4557 N Rampart St, New Orleans, LA 70117', 'Bywater', 'Outdoor', 'https://musicboxvillage.com', 'Unique outdoor venue featuring interactive musical architecture. Home of Electric Spring Festival. Also hosts regular events and rentals.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('New Orleans Jazz Museum', '400 Esplanade Ave, New Orleans, LA 70116', 'French Quarter', 'Museum', 'https://www.louisianastatemuseum.org/museum/new-orleans-jazz-museum', 'State museum dedicated to jazz history. Home of Danny Barker Festival. Also hosts FQFest programming (Loyola Esplanade in the Shade Stage and Songwriter Stage).');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('New Orleans Lakefront — Lakeshore Drive', '5000 Lakeshore Drive, New Orleans, LA 70122', 'Gentilly', 'Outdoor', 'https://www.nola.gov', 'Open lakefront grounds along Lake Pontchartrain. Home of Brews, Boils & Bubbles. Enter via Leon C. Simon under Seabrook Bridge — no entry from Franklin Ave.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Chalmette Memorial Park', '101 W. St. Bernard Hwy, Chalmette, LA 70043', NULL, 'Outdoor', NULL, 'Outdoor festival grounds in downtown Chalmette. Home of the Louisiana Crawfish Festival. About 20 min east of New Orleans in St. Bernard Parish.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('The Howlin'' Wolf', '907 S. Peters Street, New Orleans, LA 70130', 'CBD / Warehouse', 'Bar / Club', 'https://thehowlinwolf.com', 'CBD music venue. Hosts Fest by Nite shows during Jazz Fest season including Help on the Way supergroup.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Tipitina''s', '501 Napoleon Avenue, New Orleans, LA 70115', 'Uptown', 'Bar / Club', 'https://tipitinas.com', 'Legendary New Orleans music venue founded in 1977. Home of Shorty Fest, Daze Between Band, and countless iconic shows. Wheelchair accessible. Free parking nearby.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('The Joy Theater', '1037 Canal Street, New Orleans, LA 70112', 'CBD / Warehouse', 'Concert Hall', 'https://thejoytheater.com', 'Mid-sized concert hall on Canal Street. Regular Fest by Nite venue during Jazz Fest season.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('The Broadside', '600 N. Broad Street, New Orleans, LA 70119', 'Mid-City', 'Bar / Club', 'https://thebroadsideneworleans.com', 'Mid-City indoor/outdoor music venue. Home of NOLA Crawfish Fest during Jazz Fest daze between week.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Toulouse Theatre', '615 Toulouse Street, New Orleans, LA 70130', 'French Quarter', 'Concert Hall', 'https://toulousetheatre.com', 'Intimate venue in the French Quarter. Hosts Fest by Nite late shows and daze between programming during Jazz Fest season.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('d.b.a.', '618 Frenchmen Street, New Orleans, LA 70116', 'Marigny', 'Bar / Club', 'https://www.dbaneworleans.com', 'Live music club on Frenchmen Street since 2000. No cover most nights. Vast beer, wine & spirits selection. Friday open until 3am, Saturday from 2pm. Home of Tuba Skinny''s regular Saturday sets.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Gasa Gasa', '4920 Freret Street, New Orleans, LA 70115', 'Uptown', 'Bar / Club', 'https://www.gasagasanola.com', 'Intimate indie/alternative venue on Freret Street in Uptown. Known for eclectic bookings and a welcoming atmosphere.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Snug Harbor Jazz Bistro', '626 Frenchmen Street, New Orleans, LA 70116', 'Marigny', 'Bar / Club', 'https://snugjazz.com', 'Legendary intimate jazz venue anchoring Frenchmen Street since the 1980s. Two shows nightly (typically 7:30pm & 9:30pm). Full Creole dining available. Ages 13+ welcome for shows. Reservations recommended via OpenTable.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Chickie Wah Wah', '2828 Canal Street, New Orleans, LA 70119', 'Mid-City', 'Bar / Club', 'https://www.chickiewahwah.com', 'Mid-City live music club and bar. Regular venue for local and touring acts. Intimate setting with a great vibe.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Freret Street', 'Freret Street, New Orleans, LA 70115', 'Uptown', 'Outdoor', NULL, 'Six-block stretch of Uptown New Orleans from Napoleon to Valmont. Home of the annual Freret Street Festival (first Saturday of April). Vibrant mix of restaurants, bars, boutiques, and music venues.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('New Orleans Jazz Market', '1436 Oretha Castle Haley Blvd, New Orleans, LA 70113', 'CBD / Warehouse', 'Concert Hall', 'https://www.neworleansjazzmarket.com', 'Premium intimate jazz venue in the Warehouse District. Home to serious jazz performances including Stanton Moore, Donald Harrison, and other NOLA legends. Excellent acoustics and sightlines.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Saenger Theatre', '1111 Canal Street, New Orleans, LA 70112', 'CBD / Warehouse', 'Theater', 'https://www.saengernola.com', 'Beautifully restored historic theater on Canal Street. One of NOLA''s premier concert halls for major touring acts. Hosts Broadway, rock, jazz legends and more.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Civic Theatre', '510 O''Keefe Ave, New Orleans, LA 70113', 'CBD / Warehouse', 'Theater', 'https://civicnola.com', 'Historic 1930 art deco theater in the CBD. ~1,500 cap. Hosts touring acts and Jazz Fest season shows.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('The Fillmore New Orleans', '1700 Magazine St, New Orleans, LA 70130', 'CBD / Warehouse', 'Concert Hall', 'https://www.fillmorenola.com', 'Mid-size concert hall (~2,500 cap) in the Warehouse District. AEG-operated. Hosts national touring acts and Jazz Fest season shows.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Orpheum Theater', '129 Roosevelt Way, New Orleans, LA 70112', 'CBD / Warehouse', 'Theater', 'https://orpheumnola.com', 'Historic 1918 beaux-arts theater beautifully restored in 2016. ~1,500 seats. Home of the Louisiana Philharmonic Orchestra and Jazz Afterdark concert series during Jazz Fest.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('New Orleans Pharmacy Museum', '514 Chartres St, New Orleans, LA 70130', 'French Quarter', 'Outdoor', 'https://pharmacymuseum.org', 'Historic 1823 apothecary turned museum. Features a beautiful outdoor courtyard used for intimate Jazz Fest season concerts. 18+, BYOB/cash bar. Small capacity — ticket availability at door not guaranteed.');
INSERT INTO venues (name, address, neighborhood, venue_type, website, notes) VALUES ('Republic NOLA', '828 S Peters St, New Orleans, LA 70130', 'CBD / Warehouse', 'Bar / Club', 'https://republicnola.com', 'Warehouse District mid-size venue (~1,200 cap). Popular for Jazz Fest season shows and touring acts.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Rebirth Brass Band', 'Brass Band', '{"Brass","Funk","Hip-Hop / Bounce"}', 'https://rebirthbrassband.com', 'Founded 1983 in the Treme by Philip Frazier. The defining contemporary brass band — fuses traditional second line with funk, R&B, and hip-hop. Tuesday night Maple Leaf residency is legendary.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Tuba Skinny', 'Band', '{"Blues","Jazz"}', 'https://tubaskinny.com', 'Traditional New Orleans jazz band led by Shaye Cohn (cornet). Frenchmen Street institution, particularly at d.b.a. Known for their authentic early jazz and blues sound. Large international following.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Soul Rebels', 'Brass Band', '{"Brass","Funk","Hip-Hop / Bounce"}', 'https://thesoulrebels.com', 'Brass band that blends second line with hip-hop, funk, and electronic influences. Regular Thursday night residency at Le Bon Temps Roulé. Strong festival circuit presence.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Charmaine Neville', 'Solo Artist', '{"Jazz","R&B / Soul"}', NULL, 'Daughter of Charles Neville (Neville Brothers). R&B and soul vocalist. Regular Snug Harbor performer. Part of the extended Neville family musical dynasty.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Hot 8 Brass Band', 'Brass Band', '{"Brass","Hip-Hop / Bounce","R&B / Soul"}', 'https://hot8brassband.com', 'Grammy-winning brass band from Central City. Known for funk and hip-hop-inflected sound. Regular Howlin'' Wolf residency. Survived tragedy and loss to become one of NOLA''s most celebrated bands.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Preservation Hall Jazz Band', 'Band', '{"Jazz"}', 'https://preservationhall.com', 'Resident band of Preservation Hall, St. Peter St. in the French Quarter. Multiple daily shows year-round. Jazz Fest institution. Preserves and evolves the New Orleans jazz tradition.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('George Porter Jr.', 'Solo Artist', '{"Funk"}', 'https://georgeporterjr.com', 'Bassist and co-founder of The Meters, one of the most influential funk bands in history. Regular Daze Between and Jazz Fest performer. Leads his own group and collaborates widely.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Stanton Moore', 'Solo Artist', '{"Funk"}', 'https://stantonmoore.com', 'Drummer and co-founder of Galactic. Known for deep pocket New Orleans funk drumming. Regular clinician, session musician, and bandleader. Hosts annual Zildjian Jam at Tipitina''s.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Dirty Dozen Brass Band', 'Brass Band', '{"Brass","Jazz"}', 'https://dirtydozenbrass.com', 'Founded 1977 in the Treme. One of the originators of the modern brass band movement. Roger Lewis (baritone sax) inducted into Tipitina''s Walk of Fame 2026.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Big Freedia', 'Solo Artist', '{"Hip-Hop / Bounce"}', 'https://bigfreedia.com', 'Queen of Bounce. New Orleans-born LGBTQ+ icon and bounce music pioneer. Regular Jazz Fest and festival presence. Based in the 9th Ward.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Dumpstaphunk', 'Band', '{"Funk"}', 'https://dumpstaphunk.com', 'New Orleans funk supergroup featuring Ivan Neville, Tony Hall, Nick Daniels, and Raymond Weber. Ivan Neville is son of Aaron Neville. Regular Jazz Fest and Daze Between presence.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Trombone Shorty', 'Solo Artist', '{"Brass","Funk"}', 'https://tromboneshortyfoundation.org', 'Born Troy Andrews in the Treme. Founder of Trombone Shorty Foundation. Leads Orleans Avenue. Annual Shorty Fest fundraiser at Tipitina''s. Jazz Fest perennial headliner.');
INSERT INTO acts (name, act_type, genres, website, notes) VALUES ('Kermit Ruffins', 'Solo Artist', '{"Brass","Jazz"}', 'https://kermitruffins.com', 'Trumpeter, vocalist, and NOLA ambassador. Co-founder of Rebirth Brass Band. Known for BBQ cookouts before shows. Regular presence at Vaughan''s Lounge (Thursdays) and multiple festivals.');
