INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Keep''N It Real Ladies S&P Club Second Line', 'Second Line', '2026-03-08', NULL, '1:00 PM - 5:00 PM', NULL, NULL, 'Route: Starts Bayou St. John → Orleans Ave → N. Broad (stop Chill Will Barbershop) → St. Bernard → N. Claiborne (stop Da Jump Off) → Robertson (stop Hank''s Bar / Dumaine Gang) → Esplanade → Orleans Ave (stop Goldy''s / Undefeated Divas) → Disbands Club Good Times, 2901 Conti.', 'https://www.wwoz.org/events/1293256', false, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Dirk & Amelia Powell', 'Live Music', '2026-03-07', NULL, '8:00 PM', NULL, 48, 'Venue: Chickie Wah Wah', NULL, false, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Jazz Fest — Weekend 2', 'Festival', '2026-04-30', '2026-05-03', NULL, 'Ticketed', 31, 'Weekend 2 at the Fairgrounds. Headliners include Eagles, Stevie Nicks (her only 2026 show), Rod Stewart (farewell tour), Lorde, Kings of Leon, David Byrne. Check cube schedule for daily lineups.', 'https://www.nojazzfest.com', true, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Congo Square Rhythms Festival', 'Festival', '2026-03-28', '2026-03-29', NULL, 'Free', 32, 'Free weekend festival at Armstrong Park in Tremé celebrating African diaspora music, food, and dance. Features Class Got Brass school brass band competition on Saturday. No pets, no A/V recording.', 'https://www.jazzandheritage.org/events/2026-congo-square-rhythms-festival/', true, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Jazz Fest — Weekend 1', 'Festival', '2026-04-23', '2026-04-26', NULL, 'Ticketed (discounted Locals Thursday Apr 23)', 31, 'At the Fairgrounds (1751 Gentilly Blvd). 15 stages, 5000+ musicians. Headliners TBD by day — check cube schedule. Local faves include Trombone Shorty, Jon Batiste, Preservation Hall Jazz Band, Big Freedia. Cashless. Cultural Exchange Pavilion features Jamaica this year.', 'https://www.nojazzfest.com', true, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Hogs for the Cause', 'Festival', '2026-04-10', '2026-04-11', NULL, 'Ticketed', 33, 'BBQ and music festival at UNO Lakefront Arena Grounds (6801 Franklin Ave). 90+ BBQ teams, 20 musical acts, 30k+ attendees. Raises money for pediatric brain cancer families. Cashless event. Gates open 3:30pm Fri, 11am Sat. Music includes Charles Wesley Godwin, Stephen Wilson Jr., The Castellows.', 'https://hogsfest.org', true, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Electric Spring Festival', 'Festival', NULL, NULL, NULL, 'Ticketed', 36, 'New electronic music festival at Music Box Village. Features Bouffant Bouffant, Kilobauud, Dr. Romance, Legatron Prime, Funke, and more. Also visual artists, a market, and pop-ups. DATE TBD — check http://electricspringfestival.com.', 'https://electricspringfestival.com', true, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Overlook Film Festival', 'Festival', '2026-04-09', '2026-04-12', NULL, 'Ticketed', 35, 'Horror film festival at Canal Place (333 Canal St). Features independent horror cinema, interactive/live shows, a horror parade, and immersive events. Films include Obsession, Leviticus, Hokum, and Faces of Death (filmed in NOLA).', 'https://overlookfilmfest.com', false, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Giant Puppet Festival', 'Festival', '2026-04-09', '2026-04-13', NULL, 'Mixed (some free, some ticketed)', NULL, 'Multi-venue festival across Marigny/Bywater — no single home venue. Venues include Mudlark Public Theater, New Marigny Theatre, Marigny Opera House, Clouet Gardens, AllWays Lounge, CANOA, and more. Check http://neworleansgiantpuppetfest.com for full schedule and venue details.', 'https://neworleansgiantpuppetfest.com', false, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Danny Barker Banjo & Guitar Festival', 'Festival', '2026-03-27', '2026-03-29', NULL, 'Free', 37, 'Three days of music at the New Orleans Jazz Museum. Lineup includes Dirty Dozen Brass Band, Kermit Ruffins, Charmaine Neville, John Boutte, Dixie Cups, Leroy Jones, and more.', 'https://dannybarkerfestival.com', true, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('French Quarter Festival', 'Festival', '2026-04-16', '2026-04-19', NULL, 'Free (suggested $5 donation)', 34, 'Nation''s largest free Louisiana music festival. 300+ performances. Headliners include Irma Thomas, Big Freedia, Cyril Neville, PJ Morton. New this year: expanded riverfront footprint at Goldring Woldenberg Park, 5K race on Apr 18. Louisiana Fish Fry Stage features brass bands + DJ Poppa bounce sets.', 'https://frenchquarterfest.org', true, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Brews, Boils & Bubbles Festival', 'Festival', '2026-03-29', '2026-03-29', '12:00 PM – 8:00 PM', '$5 GA', 38, '3rd annual Louisiana seafood boil festival on the Lakefront. 15+ boilers and dessert vendors, craft beer, champagne, premium spirits, all-day live music. All ages (VIP 21+). From producers of the National Fried Chicken Festival. 
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Louisiana Crawfish Festival', 'Festival', '2026-03-26', '2026-03-29', NULL, 'Ticketed', 39, 'Annual crawfish festival in Chalmette. Boiled crawfish, crawfish bread, crawfish pie, crawfish jambalaya — mudbugs every which way. Live music, parade, amusement rides, games (egg tosses, sack races), food vendors. About 20 min east of NOLA.', 'https://www.lacrawfishfest.com', true, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('NOLA Crawfish Fest ⚠️ CANCELLED 2026', 'Festival', '2026-04-28', '2026-04-30', 'Gates open 3pm daily', 'Ticketed', 43, '⚠️ NOT HAPPENING IN 2026 — Confirmed cancelled per organizer (''Shaggy''). Replaced by the 1st Annual Bayou RenDAZEvous at The Broadside on Monday April 27 (also presented by Satisfied Productions). Check back for 2027. | ORIGINAL NOTES: Multi-day outdoor food and music festival at The Broadside during the daze between Jazz Fest weekends. FOOD: Hot boiled crawfish, Cajun specialties. Daytime family-friendly festival atmosphere.', 'https://thebroadsideneworleans.com', true, NULL, NULL, NULL);
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Gallatin Street Fest 2026', NULL, '2026-04-27', NULL, NULL, 'Free', 37, 'Free all-day event at the New Orleans Jazz Museum (400 Esplanade Ave). Celebrates the city''s rich musical and cultural heritage.
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Shorty Fest 2026', 'Festival', '2026-04-27', NULL, 'Outdoor 5pm / Indoor doors 7pm, show 8pm', 'Free outdoor block party. Indoor GA $125, VIP $300', 41, 'Annual fundraiser for the Trombone Shorty Foundation. Largest fundraiser for the Foundation.
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('The Daze Between Band — Tipitina''s', 'Live Music', '2026-04-29', NULL, 'Doors 9pm / Music 10pm', 'SOLD OUT', 41, '⚠️ SOLD OUT — 8th annual edition. The crown jewel of the daze between. Late-night all-star jam marking the midpoint between Jazz Fest weekends.
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Hot 8 Brass Band — Howlin'' Wolf', 'Live Music', '2026-04-05', NULL, '10:30pm', 'Free (no cover)', 40, 'Grammy-winning Hot 8 Brass Band at The Howlin'' Wolf. One of NOLA''s most celebrated brass bands, known for blending traditional second line with hip hop and soul. Late night Easter Sunday show.', 'https://thehowlinwolf.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Charmaine Neville Band — Snug Harbor', 'Live Music', '2026-04-06', NULL, '7:30pm & 9:30pm', 'Ticketed', 47, 'Two shows at Snug Harbor. Charmaine Neville is NOLA royalty — daughter of Charles Neville (The Neville Brothers), beloved jazz and R&B vocalist who has performed on Frenchmen Street for decades. A Monday night treat for friends still in town.', 'https://snugjazz.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('French Quarter Easter Parade', 'Parade', '2026-04-05', NULL, NULL, 'Free', 34, 'Annual Easter Sunday parade through the heart of the French Quarter. Floats, costumed marchers, and an Easter hat contest. Formerly known as the Chris Owens Easter Parade. A very NOLA way to spend Easter morning. Free to watch.', 'https://frenchquartereasterparade.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Stanton Moore: The Music of Allen Toussaint ft. Cyril Neville & Nicholas Payton', 'Live Music', '2026-04-04', NULL, '7:30pm', '$42', 50, 'A serious NOLA jazz event. Stanton Moore (founding drummer of Galactic, Grammy-nominated) leads a tribute to Allen Toussaint — one of NOLA''s most beloved composers and producers. Featuring Cyril Neville (The Neville Brothers) and Nicholas Payton (acclaimed jazz trumpeter). Intimate Jazz Market setting. Two shows possible — check venue for exact times.', 'https://www.neworleansjazzmarket.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('La''Trez Anderson', 'Live Music', '2026-04-03', NULL, '8pm', '$50', 40, 'Solo show at The Howlin'' Wolf.', 'https://thehowlinwolf.com', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Minx Burlesque', NULL, '2026-04-05', NULL, '6pm', 'Ticketed', 40, 'Burlesque show at The Howlin'' Wolf on Easter Sunday evening.', 'https://thehowlinwolf.com', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('ZZ Top', NULL, '2026-04-06', NULL, '8pm', 'Ticketed', 51, 'ZZ Top at the historic Saenger Theatre. Classic Texas blues rock legends. Good option for Monday night if friends are still in town.', 'https://www.saengernola.com', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Racoma / Lilly Miller', 'Live Music', '2026-04-03', NULL, '8pm', '$37', 48, 'Show at Chickie Wah Wah on Canal Street.', 'https://www.chickiewahwah.com', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Mahmoud Chouki New World Ensemble — Easter Celebration', 'Live Music', '2026-04-05', NULL, 'Two shows — check http://snugjazz.com for times', 'Ticketed', 47, 'Easter Sunday special at Snug Harbor. Two shows. Mahmoud Chouki is a celebrated Moroccan-American musician blending world music, jazz and North African traditions. A fitting Easter Sunday celebration at one of NOLA''s most intimate venues.', 'https://snugjazz.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Freret Street Festival', 'Festival', '2026-04-04', NULL, NULL, 'Free', 49, 'Annual free neighborhood street festival on Freret Street, first Saturday of April. Six blocks from Napoleon to Valmont. 3 stages, 20+ bands across jazz, funk, brass, and rock. 200+ local artists and chefs, 46 brick-and-mortar businesses open. Classic NOLA daytime festival — great for visitors. All ages.', 'https://freretstfest.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Tribute to Charlie Gabriel with Lawrence Sieberth', 'Live Music', '2026-04-04', NULL, '7:30pm & 9:30pm', 'Ticketed', 47, 'Two shows at Snug Harbor. Tribute to Charlie Gabriel, beloved NOLA jazz clarinetist. Lawrence Sieberth is a versatile pianist/composer who served as musical director for Germaine Bazzle and the Original Tuxedo Jazz Band.', 'https://snugjazz.com', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Jason Marsalis — Tribute to Brian Wilson & the Beach Boys', 'Live Music', '2026-04-03', NULL, '7:30pm & 9:30pm', 'Ticketed', 47, 'Two shows: 7:30pm & 9:30pm. Jason Marsalis is the youngest son of jazz patriarch Ellis Marsalis Jr. and one of NOLA''s most respected drummers. A uniquely New Orleans take on Brian Wilson''s iconic catalog. Intimate Snug Harbor setting on Frenchmen Street. Dinner reservations available via OpenTable before the show.', 'https://snugjazz.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Rebirth Brass Band', 'Live Music', '2026-04-04', NULL, 'Doors 7:30pm / Show 8:30pm', 'Ticketed', 41, 'Rebirth Brass Band at Tipitina''s — always a high energy show. Rebirth are one of the defining contemporary brass bands in NOLA, known for fusing traditional second line with funk, hip hop and jazz. Opening act: Sweet Magnolia. Ages 18+.', 'https://tipitinas.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Johnny Sketch & The Dirty Notes', 'Live Music', '2026-04-05', NULL, 'Doors 7pm / Show 8pm', 'Ticketed', 41, 'Easter Sunday at Tipitina''s. Johnny Sketch & The Dirty Notes are a beloved NOLA funk/soul band — high energy, deeply local. Opening act: Marc Paradis Performs Sea of Tranquility. Ages 18+.', 'https://tipitinas.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Tuba Skinny — d.b.a.', 'Live Music', '2026-04-04', NULL, '6pm - 9pm', 'Free (no cover, drink purchase)', 45, 'Tuba Skinny are one of the finest traditional jazz bands in New Orleans — rooted in 1920s-30s New Orleans jazz, blues, and hokum. No cover, just buy a drink. Saturday sets at d.b.a. are legendary. Do not miss this if you like authentic NOLA music.', 'https://www.dbaneworleans.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Rob Wagner Trio — Snug Harbor', 'Live Music', '2026-04-05', NULL, '7:30pm', 'Ticketed', 47, 'Easter Sunday show at Snug Harbor.', 'https://snugjazz.com', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Crescent City Classic 10K', 'Community / Neighborhood', '2026-04-04', NULL, 'Morning race / post-race festival all day', '~$70 to run / Free to watch', NULL, 'Annual 10K road race on Easter Saturday. Route runs from near the Caesars Superdome through the French Quarter, up through Tremé, along Esplanade Ave to City Park. Post-race festival in City Park with live music, food, drink vendors, and costume contest. Even if not running, lining up on Esplanade Ave is great people-watching. Plenty of costume runners.', 'https://ccc10k.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Loyola''s Uptown Threauxdown — Tipitina''s', NULL, '2026-04-08', NULL, 'Doors 6pm / Show 7pm', 'Ticketed', 41, 'Loyola University''s annual Uptown Threauxdown music showcase at Tipitina''s. Local student and community performers. Ages 18+.', 'https://www.ticketweb.com/event/loyolas-uptown-threauxdown-tipitinas-tickets/14126804', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Zoë de Priester''s Graduate Recital — Snug Harbor', 'Live Music', '2026-04-08', NULL, '7:30pm', 'Ticketed', 47, 'Graduate recital performance at Snug Harbor. Single show.', 'https://snugjazz.com/calendar/', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Jasen Weaver Sextet — Snug Harbor', 'Live Music', '2026-04-07', NULL, '7:30pm & 9:30pm', 'Ticketed', 47, 'Jasen Weaver Sextet at Snug Harbor. Two shows: 7:30pm & 9:30pm. Ticketed.', 'https://snugjazz.com/calendar/', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Delfeayo Marsalis & the Uptown Jazz Orchestra — Snug Harbor', 'Live Music', '2026-04-08', NULL, '7:30pm & 9:30pm', 'Ticketed', 47, 'Delfeayo Marsalis (trombonist, youngest of the Marsalis brothers) leads the Uptown Jazz Orchestra. Regular Snug Harbor booking. Two shows: 7:30pm & 9:30pm.', 'https://snugjazz.com/calendar/', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Josh, Josh & Friends — Snug Harbor', 'Live Music', '2026-04-09', NULL, '7:30pm & 9:30pm', 'Ticketed', 47, 'Josh, Josh & Friends at Snug Harbor. Two shows: 7:30pm & 9:30pm.', 'https://snugjazz.com/calendar/', false, NULL, NULL, 'Claude Agent');
