INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Booker & Beyond: Prof. Tim Piano Series feat. Josh Paxton — Maple Leaf', 'Live Music', '2026-04-09', NULL, 'Doors 5pm / Show 6pm', 'Ticketed', 20, 'Weekly Thursday Booker & Beyond Piano Series celebrating New Orleans piano traditions, honoring James Carroll Booker. This week featuring Josh Paxton. Ages 21+.', 'https://www.mapleleafbar.com/events/booker-beyond-the-professor-tim-piano-series-featuring-josh-paxton-1', false, NULL, NULL, 'Claude Agent');
