INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Happy Organ Hour: Joe Ashlar feat. Stanton Moore & Ari Teitel — Maple Leaf', 'Live Music', '2026-04-08', NULL, 'Doors 6pm / Show 7pm', 'Ticketed', 20, 'Happy Organ Hour presented by Joe Ashlar, featuring Stanton Moore (Galactic) and Ari Teitel. Weekly Wednesday organ night. Ages 21+.', 'https://www.mapleleafbar.com/events/happy-organ-hour-presented-by-joe-ashlar-with-stanton-moore-ari-teitel-1', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('NOLA Very Good Tuesday — Maple Leaf', 'Live Music', '2026-04-07', NULL, 'Show 9pm', 'Free', 20, 'Recurring weekly free improv night every Tuesday at 9pm. New Orleans'' top musicians, no covers played — only originals and improvisation. Rotating lineup, no advance ticket needed. Ages 21+.', 'https://www.mapleleafbar.com/events/nola-very-good-tuesday-1', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('James Jordan and the Situation — Maple Leaf', 'Live Music', '2026-04-09', NULL, 'Doors 7pm / Show 8pm', 'Ticketed', 20, 'James Jordan and the Situation. Ages 21+.', 'https://www.mapleleafbar.com/events/james-jordan-and-the-situation-1', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('George Porter Jr. Trio — Maple Leaf (Early & Late)', 'Live Music', '2026-04-06', NULL, 'Early 7pm / Late 10pm', 'Ticketed', 20, 'George Porter Jr. Trio — two shows same night. Early show 7pm, late show 10pm. George Porter Jr. is co-founder of The Meters. This is his regular Monday residency at the Maple Leaf. Ages 21+.', 'https://www.mapleleafbar.com/events/early-show-george-porter-jr-trio-4', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Ladyparts feat. Lynn Drury, Margie Perez & More — Maple Leaf', 'Live Music', '2026-04-03', NULL, 'Doors 7pm / Show 7:30pm', 'Ticketed', 20, 'Ladyparts showcase featuring Lynn Drury, Margie Perez and more. All-women lineup. Ages 21+.', 'https://www.mapleleafbar.com/events/ladyparts-featuring-lynn-drury-margie-perez-more', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Adam Deitch 50th Birthday Celebration — The Broadside', NULL, '2026-04-26', NULL, 'Evening', 'TBD', 43, 'Part of Fest by Nite 2026. Adam Deitch''s (Lettuce/Break Science) 50th birthday all-star celebration. PERFORMERS: Adam Deitch (drums) ft. Oteil Burbridge (bass), Ivan Neville (keys), Marcus Machado (guitar), and more TBA.', 'https://liveforlivemusic.com/news/new-orleans-jazz-fest-2026-schedule-the-cubes/', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Dogs in a Pile — Fest by Nite', 'Live Music', '2026-04-28', NULL, 'Doors 10:30pm / Show 11:30pm', 'TBD', 44, 'Part of Fest by Nite 2026. PERFORMERS: Dogs in a Pile (Jeremy Kaplan — keys/vocals, Brian Murray — guitar/vocals, Joey Babick — drums, Jimmy Law — guitar/vocals, Sam Lucid — bass). NJ jam band, third year playing Jazz Fest. Supporting new album Distroid.', 'https://liveforlivemusic.com/news/dogs-in-a-pile-2026-fest-by-nite-nola-during-jazz-fest/', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Purity Ring — House of Blues', NULL, '2026-04-29', NULL, 'Evening', 'TBD', 28, 'Canadian electronic dream-pop duo Purity Ring (Megan James + Corin Roddick) performing during Daze Between.', 'https://www.houseofblues.com/neworleans', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Grahame Lesh & Friends — Joy Theater (Night 2)', NULL, '2026-04-29', NULL, 'Doors 6:30pm / Show 7:30pm', 'TBD', 42, 'Part of Fest by Nite 2026. Night 2 of 2-night Daze Between run. Different lineup from Night 1. PERFORMERS: Grahame Lesh (guitar/vocals), Daniel Donato (guitar), Jake Brownstein (guitar, Eggy), John Molo (drums), Cory Henry (organ, Funk Apostles), Kanika Moore (vocals), Preservation Hall Horns, special guest Ivan Neville (keys/vocals, Dumpstaphunk).', 'https://liveforlivemusic.com/news/grahame-lesh-friends-joy-theater-new-orleans-jazz-fest-by-nite-2026/', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Cake — Saenger Theatre (2-Night Run)', NULL, '2026-04-28', '2026-04-29', 'Evening', 'TBD', 51, 'Sacramento alt-rock/funk band CAKE plays two nights at the Saenger during the Daze Between. Dates: April 28 & 29.', 'https://www.saengertheatre.com', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('The Radiators — Civic Theatre', NULL, '2026-04-29', NULL, 'Evening', 'TBD', 52, 'Legendary New Orleans rock band The Radiators performing during Daze Between. The Radiators are a beloved NOLA institution, playing their signature ''fishhead'' sound since the 1970s.', 'https://civicnola.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Andrew Duhon — Chickie Wah Wah', 'Live Music', '2026-04-29', NULL, 'Evening', 'TBD', 48, 'New Orleans singer-songwriter Andrew Duhon performing during Daze Between.', 'https://chickiewahwah.com', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Joe Marcinek / Dead Funk Summit — d.b.a.', 'Live Music', '2026-04-28', NULL, 'Doors 8pm / Show 9pm', '$20', 45, 'Daze Between show. Doors 8pm, show starts 9pm. Two sets: (1) Joe Marcinek opening set with Lilli Lewis, Reggie Scanlan, Bruce Sunpie Barnes, Massey, Will Murry of Iceman Special/Hollyrock. (2) Joe''s Dead Funk Summit ft. George Porter Jr., Big Sam, Tony Hall, Brad Walker, Terrence Houston, Michael Lemmler. Mix-and-match collaboration between sets promised. Only 50 presale tickets at $20.', 'https://www.dbanola.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Sgt. Splendor ft. Eric McFadden & more — Chickie Wah Wah', 'Live Music', '2026-04-29', NULL, 'Evening', 'TBD', 48, 'Daze Between show at Chickie Wah Wah. PERFORMERS: Sgt. Splendor with Eric McFadden, Kate Vargas, Charlie Wooten, and Simon Lott.', 'https://chickiewahwah.com', false, NULL, NULL, 'Claude Agent');
