INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Joe Marcinek & Dead Funk Summit — d.b.a.', 'Live Music', '2026-04-28', NULL, 'Doors 8pm / Sets from 9pm and 11pm', '$20', 45, 'TWO SETS: Early set with Joe Marcinek + Lilli Lewis, Reggie Scanlan, Bruce Sunpie Barnes, Massey, Will Murry (Iceman Special/Hollyrock). Late set: Dead Funk Summit ft. George Porter Jr. (bass, The Meters), Big Sam (trombone), Tony Hall (bass/vocals, Dumpstaphunk), Brad Walker (sax), Terrence Houston (drums), Michael Lemmler (keys). Mix-and-match collaborations across sets. Only 50 presale tickets at $20 — verify availability. Independently promoted show.', 'https://www.jazzfestforum.com/forum/main-category/jazz-fest-forum/894309-2026-nighttime-concerts-the-grids/page16', true, NULL, NULL, 'Claude Agent');
