INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Daniel Donato''s Cosmic NOLA — Civic Theatre', 'Live Music', '2026-04-30', NULL, 'Evening', 'Ticketed', 52, 'PERFORMERS: Daniel Donato''s Cosmic Country. Nashville-based guitarist/bandleader who also appears with Grahame Lesh & Friends during Daze Between. Special NOLA-themed show at Civic Theatre on Weekend 2 kickoff night.', 'https://www.nola.com/gambit/events/new-orleans-spring-concert-calendar/article_616e7ec0-abfc-41ed-80d1-b2977ff2ea41.html', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('The Motet Plays Jamiroquai — Fest by Nite', NULL, '2026-04-30', NULL, 'After midnight (technically early am 5/1)', 'Ticketed', 40, 'PERFORMERS: The Motet performing Jamiroquai tribute set. Denver-based funk/jazz band known for deep tribute performances. Part of Fest by Nite 2026 late-night at The Howlin'' Wolf.', 'https://liveforlivemusic.com/news/new-orleans-jazz-fest-2026-schedule-the-cubes/', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Adam Deitch 50th Birthday Celebration', NULL, '2026-04-26', NULL, 'Evening', 'Ticketed', 43, 'PERFORMERS: Adam Deitch (drums, Lettuce / Break Science) celebrating his 50th birthday. Guests include Oteil Burbridge (Dead & Company), Ivan Neville (Dumpstaphunk), Marcus Machado, and more TBA. Part of Fest by Nite 2026 ecosystem at The Broadside.', 'https://liveforlivemusic.com/news/new-orleans-jazz-fest-2026-schedule-the-cubes/', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('The Meters w/ Dumpstaphunk — Fest by Nite', NULL, '2026-04-24', NULL, 'Evening', 'SOLD OUT', 53, 'PERFORMERS: The Meters reunion show featuring George Porter Jr., Leo Nocentelli; with Dumpstaphunk (Ivan Neville, Tony Hall). SOLD OUT. Fest by Nite 2026. Meters also playing Saenger Theatre on Sat May 2 (also SOLD OUT).', 'https://liveforlivemusic.com/news/new-orleans-jazz-fest-2026-schedule-the-cubes/', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Sylvan Esso (DJ Set) — Fest by Nite', 'Live Music', '2026-04-26', NULL, 'Doors 9pm / Show 10pm', 'GA $30 adv / $35 DOS / VIP $65', 44, 'PERFORMERS: Sylvan Esso DJ Set (Amelia Meath + Nick Sanborn / Made of Oak). Electro-pop duo from Durham, NC. Rounds out Weekend 1 of Fest by Nite 2026. $1 from every ticket benefits Positive Legacy and Grace at the Green Light.', 'https://liveforlivemusic.com/news/sylvan-esso-dj-set-toulouse-theatre-new-orleans-jazz-fest-by-nite-2026/', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('GIVERS — Fest by Nite', NULL, '2026-04-23', NULL, 'Evening', 'Ticketed', 44, 'PERFORMERS: GIVERS (Lafayette, LA indie/rock band). Fest by Nite 2026 show at Toulouse Theatre. Also performing at Fair Grounds on Friday April 24 (Shell Gentilly Stage: GIVERS - In Light).', 'https://liveforlivemusic.com/news/new-orleans-jazz-fest-2026-schedule-the-cubes/', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Dead Feat ft. Anders Osborne, Kenny Gradney & Friends', NULL, '2026-04-30', NULL, 'Evening', 'Ticketed', 56, 'PERFORMERS: Dead Feat — a collaboration celebrating both the Grateful Dead and Little Feat, featuring Anders Osborne (guitarist, NOLA legend), Kenny Gradney (bass, Little Feat), Jackie Greene, and more. Republic NOLA. First night of Weekend 2.', 'https://www.nola.com/gambit/events/new-orleans-spring-concert-calendar/article_616e7ec0-abfc-41ed-80d1-b2977ff2ea41.html', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Gov''t Mule — Orpheum Theater', NULL, '2026-05-01', NULL, 'Evening', 'Ticketed', 54, 'PERFORMERS: Gov''t Mule — Warren Haynes (guitar/vocals), Matt Abts (drums), Danny Louis (keys/guitar/vocals), Jorgen Carlsson (bass). Full-force electric show at Orpheum — described as ''raw, electric, and built for the faithful.'' Final show of their spring headlining tour. Part of 2-night Orpheum residency (previous night: Warren Haynes Band with LPO).', 'https://orpheumnola.com', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Grahame Lesh & Friends — Fest by Nite (Night 2)', NULL, '2026-04-29', NULL, 'Doors 6:30pm / Show 7:30pm', 'Ticketed', 42, 'PERFORMERS: Grahame Lesh (guitar/bass/vocals), Jake Brownstein (guitar, Eggy), Daniel Donato (guitar, Cosmic Country), John Molo (drums), Cory Henry (organ, Funk Apostles), Kanika Moore (vocals), The Preservation Hall Horns; special guest Ivan Neville (keys/vocals, Dumpstaphunk). Night 2 of 2-night Joy Theater run during Daze Between. Part of Fest by Nite 2026.', 'https://liveforlivemusic.com/news/grahame-lesh-friends-joy-theater-new-orleans-jazz-fest-by-nite-2026/', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Karl Denson''s Tiny Universe — The Fillmore', 'Live Music', '2026-04-30', NULL, 'Evening', 'Ticketed', 53, 'PERFORMERS: Karl Denson''s Tiny Universe (Karl Denson on sax/vocals, plus full band). Jazz-funk outfit. Coincides with Weekend 2 kickoff night. Listed in Gambit spring concert calendar.', 'https://www.nola.com/gambit/events/new-orleans-spring-concert-calendar/article_616e7ec0-abfc-41ed-80d1-b2977ff2ea41.html', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Money Chicha — The Broadside', 'Live Music', '2026-04-29', NULL, 'Evening', 'TBA', 43, 'PERFORMERS: Money Chicha (psychedelic cumbia / tropical psych band). Daze Between show at The Broadside.', 'https://www.nola.com/gambit/events/new-orleans-spring-concert-calendar/article_616e7ec0-abfc-41ed-80d1-b2977ff2ea41.html', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('The Meters Reunion — Saenger Theatre', NULL, '2026-05-02', NULL, 'Evening', 'SOLD OUT', 51, 'PERFORMERS: The Meters — George Porter Jr. (bass), Leo Nocentelli (guitar), and band. SOLD OUT. Also playing Fillmore NOLA earlier in the festival week with Dumpstaphunk (also sold out). One of two major Meters reunion shows during Jazz Fest 2026 season.', 'https://liveforlivemusic.com/news/new-orleans-jazz-fest-2026-schedule-the-cubes/', false, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('The Meters — Saenger Theatre', 'Live Music', '2026-05-02', NULL, 'Evening', 'SOLD OUT', 51, 'PERFORMERS: The Meters (Leo Nocentelli, George Porter Jr., Zigaboo Modeliste). Reunion show at Saenger Theatre. SOLD OUT. Weekend 2 Saturday — same night as Lettuce/Stanton Moore/Howlin Wolf cluster. Note: separate from the Apr 24 Meters w/ Dumpstaphunk at Joy Theater (also sold out).', 'https://liveforlivemusic.com/news/new-orleans-jazz-fest-2026-schedule-the-cubes/', true, NULL, NULL, 'Claude Agent');
INSERT INTO events (name, event_type, date_start, date_end, time_info, cost, venue_id, notes, link, interested, status, series, entry_method) VALUES ('Help on the Way — Fest by Nite', NULL, '2026-04-30', NULL, 'Evening', 'Ticketed', 40, 'PERFORMERS: Help on the Way (supergroup) ft. Eric Krasno (guitar), Ross James (drums), Oteil Burbridge (bass/Dead & Co), Grahame Lesh, Ivan Neville (keys), Nikki Glaspie (drums, Dumpstaphunk), Steve Watkins. Grateful Dead-inspired all-star project. Fest by Nite 2026 at The Howlin'' Wolf. Same night as Lettuce RAGE!FEST and Stanton Moore.', 'https://liveforlivemusic.com/news/new-orleans-jazz-fest-2026-schedule-the-cubes/', true, NULL, NULL, 'Claude Agent');
